// Script to push project files to GitHub
import { getAuthenticatedUser, listRepositories, pushToRepository, getUncachableGitHubClient } from '../server/github';
import * as fs from 'fs';
import * as path from 'path';

const EXCLUDED_PATHS = [
  'node_modules',
  '.git',
  '.replit',
  '.cache',
  '.config',
  'dist',
  '.upm',
  'scripts/push-to-github.ts',
  'attached_assets',
  '.breakpoints',
  'replit.nix',
  'generated-icon.png',
  '.replit.workflow',
  'package-lock.json'
];

function shouldInclude(filePath: string): boolean {
  const relativePath = filePath.replace(/^\.\//, '');
  return !EXCLUDED_PATHS.some(excluded => 
    relativePath === excluded || relativePath.startsWith(excluded + '/')
  );
}

function getAllFiles(dir: string, files: string[] = []): string[] {
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    const relativePath = path.relative('.', fullPath);

    if (!shouldInclude(relativePath)) continue;

    if (entry.isDirectory()) {
      getAllFiles(fullPath, files);
    } else {
      files.push(relativePath);
    }
  }

  return files;
}

async function main() {
  const args = process.argv.slice(2);
  const command = args[0];

  try {
    if (command === 'user') {
      const user = await getAuthenticatedUser();
      console.log('Authenticated as:', user.login);
      console.log('Name:', user.name || 'N/A');
      console.log('Email:', user.email || 'N/A');
      return;
    }

    if (command === 'repos') {
      const repos = await listRepositories();
      console.log('Your repositories:');
      repos.slice(0, 20).forEach((repo, i) => {
        console.log(`${i + 1}. ${repo.full_name} ${repo.private ? '(private)' : '(public)'}`);
      });
      return;
    }

    if (command === 'push') {
      const repoArg = args[1]; // format: owner/repo
      const branch = args[2] || 'main';
      const message = args[3] || 'Update from Replit - ML Model Selection Feature';

      if (!repoArg) {
        console.error('Usage: npx tsx scripts/push-to-github.ts push owner/repo [branch] [message]');
        process.exit(1);
      }

      const [owner, repo] = repoArg.split('/');
      if (!owner || !repo) {
        console.error('Invalid repository format. Use: owner/repo');
        process.exit(1);
      }

      console.log(`Collecting files to push to ${owner}/${repo}...`);
      const allFiles = getAllFiles('.');
      console.log(`Found ${allFiles.length} files`);

      const files = allFiles.map(filePath => ({
        path: filePath,
        content: fs.readFileSync(filePath, 'utf-8')
      }));

      console.log(`Pushing to ${owner}/${repo} on branch ${branch}...`);
      const commit = await pushToRepository(owner, repo, branch, files, message);
      console.log('Successfully pushed!');
      console.log('Commit SHA:', commit.sha);
      console.log('Message:', commit.message);
      return;
    }

    console.log('Available commands:');
    console.log('  user  - Show authenticated user');
    console.log('  repos - List your repositories');
    console.log('  push owner/repo [branch] [message] - Push files to repository');

  } catch (error: any) {
    console.error('Error:', error.message);
    process.exit(1);
  }
}

main();

