server/replit_integrations/batch/utils.t.content:
import pLimit from "p-limit";
import pRetry from "p-retry";

/**
 * Batch Processing Utilities for Gemini
 *
 * Supported models: gemini-2.5-flash (fast), gemini-2.5-pro (advanced reasoning), gemini-2.5-flash-image (image generation)
 *
 * USAGE:
 * ```typescript
 * import { batchProcess } from "./replit_integrations/batch";
 * import { GoogleGenAI } from "@google/genai";
 *
 * const ai = new GoogleGenAI({
 *   apiKey: process.env.AI_INTEGRATIONS_GEMINI_API_KEY,
 *   httpOptions: {
 *     apiVersion: "",
 *     baseUrl: process.env.AI_INTEGRATIONS_GEMINI_BASE_URL,
 *   },
 * });
 *
 * const results = await batchProcess(
 *   items,
 *   async (item) => {
 *     const response = await ai.models.generateContent({
 *       model: "gemini-2.5-flash",
 *       contents: `Process: ${item.name}`,
 *     });
 *     return response.text || "";
 *   }
 * );
 * ```
 */

export interface BatchOptions {
  /** Max concurrent requests (default: 2) */
  concurrency?: number;
  /** Max retry attempts for rate limit errors (default: 7) */
  retries?: number;
  /** Initial retry delay in ms (default: 2000) */
  minTimeout?: number;
  /** Max retry delay in ms (default: 128000) */
  maxTimeout?: number;
  /** Callback for progress updates */
  onProgress?: (completed: number, total: number, item: unknown) => void;
}

/**
 * Check if an error is a rate limit or quota violation.
 */
export function isRateLimitError(error: unknown): boolean {
  const errorMsg = error instanceof Error ? error.message : String(error);
  return (
    errorMsg.includes("429") ||
    errorMsg.includes("RATELIMIT_EXCEEDED") ||
    errorMsg.toLowerCase().includes("quota") ||
    errorMsg.toLowerCase().includes("rate limit")
  );
}

/**
 * Process items in batches with rate limiting and automatic retries.
 *
 * @param items - Array of items to process
 * @param processor - Async function to process each item (write your LLM logic here)
 * @param options - Concurrency and retry settings
 * @returns Promise resolving to array of results in the same order as input
 */
export async function batchProcess<T, R>(
  items: T[],
  processor: (item: T, index: number) => Promise<R>,
  options: BatchOptions = {}
): Promise<R[]> {
  const {
    concurrency = 2,
    retries = 7,
    minTimeout = 2000,
    maxTimeout = 128000,
    onProgress,
  } = options;

  const limit = pLimit(concurrency);
  let completed = 0;

  const promises = items.map((item, index) =>
    limit(() =>
      pRetry(
        async () => {
          try {
            const result = await processor(item, index);
            completed++;
            onProgress?.(completed, items.length, item);
            return result;
          } catch (error: unknown) {
            if (isRateLimitError(error)) {
              throw error;
            }
            // Create an abort error to stop retrying
            const abortErr = new Error(error instanceof Error ? error.message : String(error));
            (abortErr as any).name = 'AbortError';
            throw abortErr;
          }
        },
        { retries, minTimeout, maxTimeout, factor: 2 }
      )
    )
  );

  return Promise.all(promises);
}

/**
 * Process items sequentially with SSE progress streaming.
 */
export async function batchProcessWithSSE<T, R>(
  items: T[],
  processor: (item: T, index: number) => Promise<R>,
  sendEvent: (event: { type: string; [key: string]: unknown }) => void,
  options: Omit<BatchOptions, "concurrency" | "onProgress"> = {}
): Promise<R[]> {
  const { retries = 5, minTimeout = 1000, maxTimeout = 15000 } = options;

  sendEvent({ type: "started", total: items.length });

  const results: R[] = [];
  let errors = 0;

  for (let index = 0; index < items.length; index++) {
    const item = items[index];
    sendEvent({ type: "processing", index, item });

    try {
      const result = await pRetry(() => processor(item, index), {
        retries,
        minTimeout,
        maxTimeout,
        factor: 2,
        onFailedAttempt: (error) => {
          if (!isRateLimitError(error)) {
            // Create an abort error to stop retrying
            const abortErr = new Error(error instanceof Error ? error.message : String(error));
            (abortErr as any).name = 'AbortError';
            throw abortErr;
          }
        },
      });
      results.push(result);
      sendEvent({ type: "progress", index, result });
    } catch (error) {
      errors++;
      results.push(undefined as R);
      sendEvent({
        type: "progress",
        index,
        error: error instanceof Error ? error.message : "Processing failed",
      });
    }
  }

  sendEvent({ type: "complete", processed: items.length, errors });
  return results;
}

server/models/roboflow-service.ts.content:
import fetch from 'node-fetch';
import type { AnalysisResponse, DetectionResult } from './config';
import { storage } from '../storage';

interface RoboflowPrediction {
  x: number;
  y: number;
  width: number;
  height: number;
  confidence: number;
  class: string;
  class_id: number;
}

interface RoboflowResponse {
  predictions: RoboflowPrediction[];
  image: {
    width: number;
    height: number;
  };
}

export class RoboflowService {
  private projectId: string;
  private modelVersion: string;

  constructor() {
    this.projectId = process.env.ROBOFLOW_PROJECT_ID || 'warehouse-inventory';
    this.modelVersion = process.env.ROBOFLOW_MODEL_VERSION || '1';
  }

  async analyzeImage(
    base64Image: string,
    modelName: string,
    userInstructions?: string[]
  ): Promise<AnalysisResponse> {
    // Get API key from settings (server-side only)
    const apiKeySetting = await storage.getSetting('roboflow_api_key');
    const apiKey = apiKeySetting?.value || process.env.ROBOFLOW_API_KEY;

    if (!apiKey) {
      throw new Error('ROBOFLOW_API_KEY is not configured. Please add it in Settings or set the ROBOFLOW_API_KEY environment variable.');
    }

    const base64Data = base64Image.replace(/^data:image\/\w+;base64,/, '');

    const url = `https://detect.roboflow.com/${this.projectId}/${this.modelVersion}?api_key=${apiKey}&confidence=40`;

    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: `image=${encodeURIComponent(base64Data)}`,
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`Roboflow API error: ${response.status} - ${errorText}`);
      }

      const data = await response.json() as RoboflowResponse;

      const itemCounts = new Map<string, {
        count: number;
        totalConfidence: number;
        locations: string[];
        boundingBoxes: Array<{ x: number; y: number; width: number; height: number }>;
      }>();

      data.predictions.forEach(pred => {
        const className = pred.class;
        const existing = itemCounts.get(className) || {
          count: 0,
          totalConfidence: 0,
          locations: [],
          boundingBoxes: []
        };

        existing.count++;
        existing.totalConfidence += pred.confidence;
        existing.boundingBoxes.push({
          x: pred.x,
          y: pred.y,
          width: pred.width,
          height: pred.height
        });

        const location = this.getLocationDescription(pred, data.image.width, data.image.height);
        if (location && !existing.locations.includes(location)) {
          existing.locations.push(location);
        }

        itemCounts.set(className, existing);
      });

      const detectedItems: DetectionResult[] = Array.from(itemCounts.entries()).map(([itemType, data]) => {
        const avgConfidence = Math.round((data.totalConfidence / data.count) * 100);

        return {
          itemType,
          count: data.count,
          confidence: avgConfidence,
          location: data.locations.length > 0 ? data.locations.join(', ') : null,
          boundingBox: data.boundingBoxes[0]
        };
      });

      const totalItems = detectedItems.reduce((sum, item) => sum + item.count, 0);
      const imageDescription = this.generateImageDescription(detectedItems, totalItems);

      return {
        detectedItems,
        totalItems,
        imageDescription,
        modelType: 'cnn',
        modelName
      };
    } catch (error) {
      console.error('Roboflow analysis error:', error);
      throw new Error(`Failed to analyze image with Roboflow: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  private getLocationDescription(
    pred: RoboflowPrediction,
    imageWidth: number,
    imageHeight: number
  ): string | null {
    const centerX = pred.x;
    const centerY = pred.y;

    const horizontal = centerX < imageWidth / 3 ? 'left' 
      : centerX > (2 * imageWidth) / 3 ? 'right' 
      : 'center';

    const vertical = centerY < imageHeight / 3 ? 'top'
      : centerY > (2 * imageHeight) / 3 ? 'bottom'
      : 'middle';

    if (horizontal === 'center' && vertical === 'middle') {
      return 'center';
    }

    return `${vertical} ${horizontal}`;
  }

  private generateImageDescription(items: DetectionResult[], total: number): string {
    if (items.length === 0) {
      return 'No objects detected in the warehouse image.';
    }

    const itemDescriptions = items.map(item => 
      `${item.count} ${item.itemType}${item.count > 1 ? 's' : ''}`
    ).join(', ');

    return `Warehouse image containing ${total} total items: ${itemDescriptions}`;
  }
}

export const roboflowService = new RoboflowService();

